//! The fluidity matrix: every OS pair, every side, several screen sizes and
//! every hand-off a person makes, each held to the "extra monitor" goals of
//! `docs/testing/handoff-fluidity.md`:
//!
//! - the cursor moves on the other screen within one frame of the crossing;
//! - it enters where it left (proportionally), within 1.5 px;
//! - coming back works at once, also 50 ms after crossing, without
//!   ping-pong at the border;
//! - either PC's own mouse and keyboard can take over at any time;
//! - nothing is ever left pressed, on either PC.
//!
//! `fluidity_matrix.rs` (generated by `scripts/gen-fluidity-matrix.py`)
//! declares one test per case; the short subset runs with `cargo test`, the
//! full matrix with `cargo test -- --ignored` (weekly CI job).

use std::time::Duration;

use input_capture::Position;
use tokio::task::LocalSet;

use super::{
    Desk, Focus, Hand, Personality,
    metrics::{MAX_CROSSING_LATENCY, MAX_ENTRY_ERROR_PX, outward},
};

const BTN_LEFT: u32 = 0x110;
const KEY_A: u32 = 30;
const KEY_RIGHTALT: u32 = 100;
const KEY_RIGHTSHIFT: u32 = 54;
const KEY_0: u32 = 11;

/// The hand-off a person makes.
#[derive(Clone, Copy, Debug)]
pub(crate) enum Scenario {
    /// cross by a few px and stop
    CrossAndStop,
    /// cross, move around, come back
    RoundTrip,
    /// cross and come straight back 50 ms later
    QuickReturn,
    /// cross at the very start / end of the edge
    EdgeStart,
    EdgeEnd,
    /// cross near (not at) the corners
    NearCornerLow,
    NearCornerHigh,
    /// a slow 1 px crawl over the edge (125 Hz)
    SlowCrawl,
    /// a fast flick (40 px events)
    Flick,
    /// reach the edge holding a button (default policy: hold)
    DragHold,
    /// reach the edge holding a button with `drag_across = "cross"`
    DragCross,
    /// the other PC's own mouse takes over while it is being driven
    HandSwitch,
    /// both mice move at the same time
    BothMice,
    /// a key held while coming back is released on the PC left behind
    KeyHeldAcrossReturn,
    /// the switch hotkey brings the keyboard home from either side
    HotkeyFromEither,
}

impl Scenario {
    /// Needs the target PC to drive the source too.
    fn needs_two_hands(self) -> bool {
        matches!(
            self,
            Scenario::HandSwitch | Scenario::BothMice | Scenario::HotkeyFromEither
        )
    }

    fn hand(self) -> Hand {
        match self {
            Scenario::SlowCrawl => Hand {
                step_px: 1.0,
                interval: Duration::from_millis(8),
            },
            Scenario::Flick => Hand {
                step_px: 40.0,
                interval: Duration::from_millis(1),
            },
            _ => Hand::default(),
        }
    }
}

/// One cell of the matrix.
#[derive(Clone, Debug)]
pub(crate) struct Case {
    pub(crate) source: fn() -> Personality,
    pub(crate) target: fn() -> Personality,
    /// side of the source the target sits at
    pub(crate) side: Position,
    /// `(source w, h, target w, h)` in logical px
    pub(crate) sizes: (u32, u32, u32, u32),
    pub(crate) scenario: Scenario,
}

/// Screen size pairs of the matrix: equal, the user's laptop (1536x960
/// logical at 5/3) next to a 1440p monitor, and a small screen next to 4K.
pub(crate) const SIZES: [(u32, u32, u32, u32); 3] = [
    (1920, 1080, 1920, 1080),
    (1536, 960, 2560, 1440),
    (1280, 800, 3840, 2160),
];

fn init_log() {
    let _ = env_logger::builder()
        .is_test(true)
        .parse_env(env_logger::Env::new().filter("LAN_MOUSE_LOG_LEVEL"))
        .try_init();
}

/// Run one matrix case on a fresh desk (A = source, holds the first mouse;
/// B = target, with its own mouse and keyboard too).
pub(crate) fn run(case: Case) {
    let source = (case.source)();
    let target = (case.target)();
    if case.scenario.needs_two_hands() && !target.capture_available {
        // the target OS cannot drive anyone (X11): nothing to test
        return;
    }
    init_log();
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    runtime.block_on(LocalSet::new().run_until(async move {
        let (sw, sh, tw, th) = case.sizes;
        let mut builder = Desk::builder()
            .pc("A", sw, sh)
            .pc("B", tw, th)
            .place("B", case.side, "A")
            .place("A", case.side.opposite(), "B")
            .personality("A", source)
            .personality("B", target)
            .hand(case.scenario.hand());
        if matches!(case.scenario, Scenario::DragCross) {
            builder = builder.top_config("A", "drag_across = \"cross\"");
        }
        let desk = builder.start().await;
        play(&desk, &case).await;
        let stuck = desk.stuck_inputs();
        assert!(stuck.is_empty(), "{case:?}: {stuck:?}\n{}", desk.report());
    }));
}

async fn play(desk: &Desk, case: &Case) {
    let side = case.side;
    match case.scenario {
        Scenario::CrossAndStop => {
            cross(desk, "A", side, 0.5).await;
            assert_fluid_crossing(desk, case, "A", "B");
            rests_on(desk, case, "B").await;
            assert_single_handoff(desk, case);
        }
        Scenario::RoundTrip => {
            cross(desk, "A", side, 0.3).await;
            // around on B, then back through the entry edge
            let (ox, oy) = outward(side);
            let (lx, ly) = lateral(side);
            desk.move_mouse_on("A", ox * 200.0 + lx * 150.0, oy * 200.0 + ly * 150.0)
                .await;
            desk.move_mouse_on("A", -ox * 800.0, -oy * 800.0).await;
            desk.wait_focus("A").await;
            rests_on(desk, case, "A").await;
            assert_return_continuity(desk, case);
            assert_single_handoff(desk, case);
        }
        Scenario::QuickReturn => {
            cross(desk, "A", side, 0.5).await;
            tokio::time::sleep(Duration::from_millis(50)).await;
            let (ox, oy) = outward(side);
            desk.move_mouse_on("A", -ox * 300.0, -oy * 300.0).await;
            desk.wait_until(
                &format!("{case:?}: back on A after a quick return"),
                Duration::from_secs(2),
                |d| d.focus() == Focus::On("A"),
            )
            .await;
            rests_on(desk, case, "A").await;
            assert_single_handoff(desk, case);
        }
        Scenario::EdgeStart | Scenario::EdgeEnd => {
            let along = if matches!(case.scenario, Scenario::EdgeStart) {
                0.0
            } else {
                1.0
            };
            cross(desk, "A", side, along).await;
            assert_fluid_crossing(desk, case, "A", "B");
            rests_on(desk, case, "B").await;
        }
        Scenario::NearCornerLow | Scenario::NearCornerHigh => {
            let along = if matches!(case.scenario, Scenario::NearCornerLow) {
                0.03
            } else {
                0.97
            };
            cross(desk, "A", side, along).await;
            assert_fluid_crossing(desk, case, "A", "B");
            rests_on(desk, case, "B").await;
        }
        Scenario::SlowCrawl | Scenario::Flick => {
            cross(desk, "A", side, 0.6).await;
            assert_entry(desk, case, "A", "B");
            rests_on(desk, case, "B").await;
            assert_single_handoff(desk, case);
        }
        Scenario::DragHold => {
            desk.button_on("A", BTN_LEFT, 1).await;
            desk.approach_edge("A", side, 0.5).await;
            push(desk, "A", side, 60.0).await;
            // what a person sees: the cursor stays on A, the drag goes on
            desk.hold(
                &format!("{case:?}: a drag stays on A"),
                Duration::from_millis(300),
                |d| d.focus() == Focus::On("A"),
            )
            .await;
            assert!(
                desk.pc("A").state().app_buttons.contains(&BTN_LEFT),
                "{case:?}: the drag on A was broken off\n{}",
                desk.report()
            );
            desk.button_on("A", BTN_LEFT, 0).await;
            // dropped: the edge comes back and leads to B
            desk.wait_until(
                &format!("{case:?}: A's edge back after the drop"),
                Duration::from_secs(1),
                |d| d.pc("A").state().barriers.contains(&side),
            )
            .await;
            push(desk, "A", side, 60.0).await;
            desk.wait_focus("B").await;
            assert!(
                !desk.pc("B").state().app_buttons.contains(&BTN_LEFT),
                "{case:?}: B got a button press"
            );
        }
        Scenario::DragCross if (case.source)().begin_on_edge_touch => {
            // layer-shell: the Wayland implicit grab keeps the pointer on the
            // dragging app, so a drag always stays on this screen
            desk.button_on("A", BTN_LEFT, 1).await;
            desk.approach_edge("A", side, 0.5).await;
            push(desk, "A", side, 60.0).await;
            desk.hold(
                &format!("{case:?}: a Wayland drag stays on A"),
                Duration::from_millis(300),
                |d| d.focus() == Focus::On("A"),
            )
            .await;
            desk.button_on("A", BTN_LEFT, 0).await;
        }
        Scenario::DragCross => {
            desk.button_on("A", BTN_LEFT, 1).await;
            desk.approach_edge("A", side, 0.5).await;
            push(desk, "A", side, 60.0).await;
            desk.wait_focus("B").await;
            // the drag ended at A's edge: A's app got the release
            desk.wait_until(
                &format!("{case:?}: A's app released the dragged button"),
                Duration::from_secs(2),
                |d| !d.pc("A").state().app_buttons.contains(&BTN_LEFT),
            )
            .await;
            desk.button_on("A", BTN_LEFT, 0).await;
            rests_on(desk, case, "B").await;
        }
        Scenario::HandSwitch => {
            cross(desk, "A", side, 0.5).await;
            desk.wait_focus("B").await;
            // somebody grabs B's own mouse
            let (ox, oy) = outward(side);
            let (lx, ly) = lateral(side);
            desk.move_mouse_on("B", ox * 120.0 + lx * 40.0, oy * 120.0 + ly * 40.0)
                .await;
            if (case.target)().detects_local_input {
                // the last hand that moved wins: A lets go of B
                desk.wait_until(
                    &format!("{case:?}: A let go of B once B's mouse moved"),
                    Duration::from_secs(2),
                    |d| {
                        d.pc("A").state().captured.is_none()
                            && d.pc("B").state().remote_edge.is_none()
                    },
                )
                .await;
                desk.hold(
                    &format!("{case:?}: each mouse on its own PC"),
                    Duration::from_millis(300),
                    |d| d.focus_from("A") == Focus::On("A") && d.focus_from("B") == Focus::On("B"),
                )
                .await;
            } else {
                // B cannot tell its own mouse from A's: both move B's cursor
                // and A keeps driving until A's hand comes back
                desk.move_mouse_on("A", -ox * 600.0, -oy * 600.0).await;
                desk.wait_focus("A").await;
            }
            // and A can cross again afterwards
            cross(desk, "A", side, 0.5).await;
            desk.wait_focus("B").await;
        }
        Scenario::BothMice => {
            cross(desk, "A", side, 0.5).await;
            let (ox, oy) = outward(side);
            let (lx, ly) = lateral(side);
            // A keeps pushing into B while B's user wiggles B's mouse
            let a = desk.move_mouse_on("A", ox * 400.0 + lx * 300.0, oy * 400.0 + ly * 300.0);
            let b = async {
                for _ in 0..4 {
                    desk.move_mouse_on("B", lx * 80.0, ly * 80.0).await;
                    desk.move_mouse_on("B", -lx * 80.0, -ly * 80.0).await;
                }
            };
            let watch = async {
                let end = std::time::Instant::now() + Duration::from_millis(400);
                while std::time::Instant::now() < end {
                    assert_no_loop(desk, case);
                    tokio::time::sleep(Duration::from_millis(1)).await;
                }
            };
            tokio::join!(a, b, watch);
            desk.hold(
                &format!("{case:?}: no loop after both mice moved"),
                Duration::from_millis(300),
                |d| !(d.pc("A").state().captured.is_some() && d.pc("B").state().captured.is_some()),
            )
            .await;
        }
        Scenario::KeyHeldAcrossReturn => {
            cross(desk, "A", side, 0.5).await;
            desk.wait_focus("B").await;
            lock_screen_key(desk, "A", KEY_A, 1);
            let (ox, oy) = outward(side);
            desk.move_mouse_on("A", -ox * 400.0, -oy * 400.0).await;
            desk.wait_focus("A").await;
            lock_screen_key(desk, "A", KEY_A, 0);
            desk.wait_until(
                &format!("{case:?}: B's app saw the key go up"),
                Duration::from_secs(2),
                |d| d.pc("B").state().app_keys.is_empty(),
            )
            .await;
        }
        Scenario::HotkeyFromEither => {
            cross(desk, "A", side, 0.5).await;
            desk.wait_focus("B").await;
            desk.key_chord_on("A", &[KEY_RIGHTALT, KEY_RIGHTSHIFT, KEY_0])
                .await;
            desk.wait_until(
                &format!("{case:?}: A's hotkey brought A's keyboard home"),
                Duration::from_secs(2),
                |d| d.focus_from("A") == Focus::On("A"),
            )
            .await;
            // now B's own mouse crosses into A and B's hotkey brings it home
            cross(desk, "B", side.opposite(), 0.5).await;
            desk.wait_focus_from("B", "A").await;
            desk.key_chord_on("B", &[KEY_RIGHTALT, KEY_RIGHTSHIFT, KEY_0])
                .await;
            desk.wait_until(
                &format!("{case:?}: B's hotkey brought B's keyboard home"),
                Duration::from_secs(2),
                |d| d.focus_from("B") == Focus::On("B"),
            )
            .await;
        }
    }
}

fn lock_screen_key(desk: &Desk, name: &str, key: u32, state: u8) {
    super::lock(&desk.pc(name).screen).key_event(key, state);
}

/// Walk `name`'s cursor to its `side` edge at `along` and cross it.
async fn cross(desk: &Desk, name: &'static str, side: Position, along: f64) {
    desk.approach_edge(name, side, along).await;
    push(desk, name, side, 40.0).await;
    let target = desk
        .neighbour(name, side)
        .unwrap_or_else(|| panic!("{name} has no PC at {side:?}"))
        .name;
    desk.wait_focus_from(name, target).await;
}

async fn push(desk: &Desk, name: &str, side: Position, px: f64) {
    let (ox, oy) = outward(side);
    desk.move_mouse_on(name, ox * px, oy * px).await;
}

/// A direction along the edge of `side`.
fn lateral(side: Position) -> (f64, f64) {
    match side {
        Position::Left | Position::Right => (0.0, 1.0),
        Position::Top | Position::Bottom => (1.0, 0.0),
    }
}

/// The cursor stays on `name` with the hand still: no ping-pong.
async fn rests_on(desk: &Desk, case: &Case, name: &'static str) {
    desk.hold(
        &format!("{case:?}: the cursor rests on {name}"),
        Duration::from_millis(300),
        |d| d.focus() == Focus::On(name),
    )
    .await;
}

fn assert_fluid_crossing(desk: &Desk, case: &Case, source: &str, target: &str) {
    let latency = desk
        .crossing_latency(source, target)
        .unwrap_or_else(|| panic!("{case:?}: no motion reached {target}\n{}", desk.report()));
    assert!(
        latency <= MAX_CROSSING_LATENCY,
        "{case:?}: the cursor moved on {target} {latency:?} after the crossing\n{}",
        desk.report()
    );
    assert_entry(desk, case, source, target);
}

fn assert_entry(desk: &Desk, case: &Case, source: &str, target: &str) {
    let error = desk
        .entry_error_px(source, target)
        .unwrap_or_else(|| panic!("{case:?}: {target} got no entry point\n{}", desk.report()));
    assert!(
        error <= MAX_ENTRY_ERROR_PX,
        "{case:?}: entered {error:.1} px away from the crossing point\n{}",
        desk.report()
    );
}

/// Where B's cursor left must be where A's cursor came back.
fn assert_return_continuity(desk: &Desk, case: &Case) {
    let Some((edge, along)) = desk.pc("A").last_return() else {
        panic!(
            "{case:?}: A came back without a return point\n{}",
            desk.report()
        );
    };
    assert_eq!(edge, case.side, "{case:?}");
    let left_b = desk.pc("B").last_leave_along();
    let Some(left_b) = left_b else {
        panic!(
            "{case:?}: B never reported where it left\n{}",
            desk.report()
        );
    };
    let span = {
        let state = desk.pc("A").state();
        match case.side {
            Position::Left | Position::Right => state.height - 1.0,
            _ => state.width - 1.0,
        }
    };
    let error = (f64::from(along) - f64::from(left_b)).abs() * span;
    assert!(
        error <= MAX_ENTRY_ERROR_PX + 1.0,
        "{case:?}: came back {error:.1} px away from where it left B\n{}",
        desk.report()
    );
}

/// One crossing each way at most: no ping-pong behind the person's back.
fn assert_single_handoff(desk: &Desk, case: &Case) {
    let begins = desk.pc("A").capture_begins();
    assert_eq!(
        begins,
        1,
        "{case:?}: A captured {begins} times\n{}",
        desk.report()
    );
}

/// A drives B while B drives A: the input would go round in a circle.
fn assert_no_loop(desk: &Desk, case: &Case) {
    let a = desk.pc("A").state();
    let b = desk.pc("B").state();
    let looping = a.captured.is_some()
        && b.captured.is_some()
        && a.remote_edge.is_some()
        && b.remote_edge.is_some();
    drop((a, b));
    assert!(
        !looping,
        "{case:?}: A and B drive each other\n{}",
        desk.report()
    );
}
